<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('documents.manage'); $bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); try{$u=safe_upload('document','documents'); if(!$u) throw new RuntimeException('Choose a file.'); q('INSERT INTO documents(branch_id,entity_type,entity_id,title,file_path,original_name,mime_type,uploaded_by,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())',[$bid,$_POST['entity_type'],(int)($_POST['entity_id']??0)?:null,trim($_POST['title']),$u['path'],$u['original'],$u['mime'],$_SESSION['user_id']]); flash('success','Document uploaded.');}catch(Throwable $e){flash('error',$e->getMessage());} redirect('modules/documents.php');}
$rows=all('SELECT d.*,u.username FROM documents d LEFT JOIN users u ON u.id=d.uploaded_by WHERE d.branch_id=? ORDER BY d.id DESC',[$bid]); $title='Document Storage'; $subtitle='Attach contracts, invoices, warranty cards, receipts and certificates.'; include dirname(__DIR__).'/includes/header.php';?><section class="card"><h2>Upload Document</h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><div class="form-grid"><div class="form-group"><label>Title</label><input name="title" required></div><div class="form-group"><label>Attach To</label><select name="entity_type"><option value="staff">Employee</option><option value="supplier">Supplier</option><option value="equipment">Equipment</option><option value="purchase">Purchase</option><option value="expense">Expense</option><option value="customer">Customer</option><option value="other">Other</option></select></div><div class="form-group"><label>Record ID (optional)</label><input type="number" name="entity_id"></div><div class="form-group"><label>File</label><input type="file" name="document" required></div></div><button class="btn">Upload</button></form></section><div class="table-wrap"><table><thead><tr><th>Date</th><th>Title</th><th>Type</th><th>Record ID</th><th>File</th><th>User</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['title'])?></td><td><?=e($r['entity_type'])?></td><td><?=e($r['entity_id'])?></td><td><a class="btn small light" href="download.php?id=<?=e($r['id'])?>">Download</a></td><td><?=e($r['username'])?></td></tr><?php endforeach;?></tbody></table></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>